  (Handle : Ada.Text_IO.File_Type)
is
   Found_One : Boolean := False;
begin
   Ada.Text_IO.Put_Line (Handle, "============================");
   Ada.Text_IO.Put_Line (Handle, "Most difficult proved checks");
   Ada.Text_IO.Put_Line (Handle, "============================");
